import { readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const corePath = join(root, "packages", "mining-core", "src", "index.js");
const cliPath = join(root, "tooling", "skill-runner-cli.mjs");
const outputPath = join(
  root,
  ".agents",
  "skills",
  "indie-keyword-finder",
  "scripts",
  "mine.mjs",
);

const generated = [
  "// Generated from packages/mining-core/src/index.js.",
  "// Run `npm run generate:skill`; do not edit this file directly.",
  "",
  (await readFile(corePath, "utf8")).trimEnd(),
  "",
  (await readFile(cliPath, "utf8")).trim(),
  "",
].join("\n");

if (process.argv.includes("--check")) {
  const current = await readFile(outputPath, "utf8").catch(() => "");
  if (current !== generated) {
    console.error(
      "Companion Skill runner is stale. Run `npm run generate:skill`.",
    );
    process.exit(1);
  }
  console.log("Companion Skill runner matches Mining Core.");
} else {
  await writeFile(outputPath, generated);
  console.log(`Generated Companion Skill runner: ${outputPath}`);
}
